{
  "name": "FV Grupo Empresarial - Dashboard de Ventas",
  "description": "Dashboard interactivo para el seguimiento de metas y KPIs de ventas semanales para FV Grupo Empresarial, con análisis de IA y visualización de datos en tiempo real.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface GoalStat {
  meta: number;
  real: number;
}

export interface RouteData {
  id: string;
  name: string;
  clients: GoalStat;
  boxes: GoalStat;
  collection: GoalStat;
  divisas: number; // Cash portion of collection
}

export interface Analysis {
  diagnostic: string;
  painPoint: string;
  opportunity: string;
}

import React, { useState, useMemo } from 'react';
import { RouteData } from './types';
import DashboardView from './components/DashboardView';
import { BarChart3, TrendingUp, Users, Wallet, ChevronRight } from 'lucide-react';

const INITIAL_DATA: RouteData[] = [
  {
    id: 'guanare',
    name: 'GUANARE',
    clients: { meta: 45, real: 42 },
    boxes: { meta: 800, real: 520 },
    collection: { meta: 25000, real: 18000 },
    divisas: 12000
  },
  {
    id: 'sabaneta',
    name: 'SABANETA',
    clients: { meta: 38, real: 39 },
    boxes: { meta: 650, real: 610 },
    collection: { meta: 18000, real: 17500 },
    divisas: 5000
  }
];

const App: React.FC = () => {
  const [routes, setRoutes] = useState<RouteData[]>(INITIAL_DATA);
  const [activeRouteId, setActiveRouteId] = useState<string>(INITIAL_DATA[0].id);

  const activeRoute = useMemo(() => 
    routes.find(r => r.id === activeRouteId) || routes[0], 
    [routes, activeRouteId]
  );

  const handleUpdateData = (updatedRoute: RouteData) => {
    setRoutes(prev => prev.map(r => r.id === updatedRoute.id ? updatedRoute : r));
  };

  return (
    <div className="min-h-screen pb-12">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-[#2E86C1] p-2 rounded-lg">
                <BarChart3 className="text-white w-6 h-6" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-900 tracking-tight">FV Grupo Empresarial</h1>
                <p className="text-xs text-slate-500 font-medium">Dashboard de Mando Semanal: 09/02/2026 - 15/02/2026</p>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-4">
              <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                Estado: Actualizado
              </span>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 overflow-x-auto">
          <nav className="flex space-x-8" aria-label="Tabs">
            {routes.map((route) => (
              <button
                key={route.id}
                onClick={() => setActiveRouteId(route.id)}
                className={`
                  whitespace-nowrap py-4 px-1 border-b-2 font-medium text-sm transition-all duration-200
                  ${activeRouteId === route.id
                    ? 'border-[#2E86C1] text-[#2E86C1]'
                    : 'border-transparent text-slate-500 hover:text-slate-700 hover:border-slate-300'
                  }
                `}
              >
                Vendedor: {route.name}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-8">
        <DashboardView 
          route={activeRoute} 
          onUpdate={handleUpdateData} 
        />
      </main>

      <footer className="mt-20 border-t border-slate-200 py-8 bg-white">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-sm text-slate-400">© 2026 FV Grupo Empresarial. Sistema de Inteligencia Comercial B2B.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { RouteData } from '../types';
import { Settings2 } from 'lucide-react';

interface EditableTableProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const EditableTable: React.FC<EditableTableProps> = ({ route, onUpdate }) => {
  const handleChange = (field: keyof RouteData, subField: string, value: string) => {
    const numValue = parseFloat(value) || 0;
    const updated = { ...route };

    if (field === 'divisas') {
      updated.divisas = numValue;
    } else if (field === 'clients' || field === 'boxes' || field === 'collection') {
      const stat = updated[field] as { meta: number, real: number };
      if (subField === 'meta') stat.meta = numValue;
      if (subField === 'real') stat.real = numValue;
    }

    onUpdate(updated);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50 flex items-center gap-2">
        <Settings2 className="w-4 h-4 text-slate-400" />
        <h3 className="text-sm font-semibold text-slate-700 uppercase tracking-wider">Editor de Datos: {route.name}</h3>
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-200">
          <thead>
            <tr className="bg-white">
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Indicador</th>
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Meta</th>
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Real</th>
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Detalle Adicional</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-100">
            {/* Clientes */}
            <tr>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-700">Clientes (Activación)</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.meta}
                  onChange={(e) => handleChange('clients', 'meta', e.target.value)}
                  className="w-24 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.real}
                  onChange={(e) => handleChange('clients', 'real', e.target.value)}
                  className="w-24 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap text-xs text-slate-500">Número de puntos de venta</td>
            </tr>
            {/* Cajas */}
            <tr>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-700">Volumen (Cajas)</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.boxes.meta}
                  onChange={(e) => handleChange('boxes', 'meta', e.target.value)}
                  className="w-24 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.boxes.real}
                  onChange={(e) => handleChange('boxes', 'real', e.target.value)}
                  className="w-24 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap text-xs text-slate-500">Cajas físicas distribuidas</td>
            </tr>
            {/* Cobranza */}
            <tr>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-700">Cobranza Total (Bs + $)</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.collection.meta}
                  onChange={(e) => handleChange('collection', 'meta', e.target.value)}
                  className="w-32 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.collection.real}
                  onChange={(e) => handleChange('collection', 'real', e.target.value)}
                  className="w-32 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] text-slate-400 font-bold uppercase">De los cuales Divisas ($):</label>
                  <input 
                    type="number" 
                    value={route.divisas}
                    onChange={(e) => handleChange('divisas', '', e.target.value)}
                    className="w-32 px-2 py-1 border border-slate-200 rounded text-sm focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                  />
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default EditableTable;

import React, { useMemo } from 'react';
import { RouteData } from '../types';
import EditableTable from './EditableTable';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell,
  PieChart, Pie
} from 'recharts';
import { BrainCircuit, AlertTriangle, Lightbulb, TrendingDown, Target } from 'lucide-react';

interface DashboardViewProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ route, onUpdate }) => {
  // Helper to calculate traffic light colors
  const getSemaphoreColor = (real: number, meta: number) => {
    if (meta <= 0) return '#27AE60';
    const percent = (real / meta) * 100;
    if (percent < 70) return '#E74C3C'; // Rojo
    if (percent <= 90) return '#F1C40F'; // Amarillo
    return '#27AE60'; // Verde
  };

  const barData = useMemo(() => [
    { name: 'Clientes', meta: route.clients.meta, real: route.clients.real, color: getSemaphoreColor(route.clients.real, route.clients.meta) },
    { name: 'Cajas', meta: route.boxes.meta, real: route.boxes.real, color: getSemaphoreColor(route.boxes.real, route.boxes.meta) },
    { name: 'Cobranza', meta: route.collection.meta, real: route.collection.real, color: getSemaphoreColor(route.collection.real, route.collection.meta) },
  ], [route]);

  const pieData = useMemo(() => {
    const digital = Math.max(0, route.collection.real - route.divisas);
    return [
      { name: 'Bs. Digital', value: digital, color: '#3498DB' },
      { name: 'Divisas Cash', value: route.divisas, color: '#2ECC71' }
    ];
  }, [route]);

  const analysis = useMemo(() => {
    const clientPerf = (route.clients.real / (route.clients.meta || 1)) * 100;
    const boxesPerf = (route.boxes.real / (route.boxes.meta || 1)) * 100;

    let diag = `${route.name}, buen esfuerzo esta semana. `;
    let pain = "";
    let opp = "";

    if (clientPerf > 90 && boxesPerf < 75) {
      diag += "Tu cobertura de clientes es sólida, indicando que recorres la ruta completa.";
      pain = "Sin embargo, el volumen por cliente es bajo. Estás visitando, pero no profundizando en el pedido.";
      opp = "Enfócate en la venta sugestiva de licores premium o promociones especiales para elevar el ticket promedio.";
    } else if (clientPerf < 70) {
      diag += "Vemos que el volumen se mantiene, pero la base de clientes activos está disminuyendo.";
      pain = "Estás dependiendo de pocos clientes grandes. Si uno falla, la ruta cae drásticamente.";
      opp = "Dedica los primeros dos días de la próxima semana a la recuperación de clientes inactivos o 'dormidos'.";
    } else if (boxesPerf > 95) {
      diag += "¡Excelente volumen de ventas! Has superado las expectativas de distribución.";
      pain = "Asegúrate de que la cobranza vaya al ritmo de los pedidos para no afectar el flujo de caja.";
      opp = "Aprovecha este impulso para introducir nuevos SKUs de baja rotación en tus clientes estrella.";
    } else {
      diag += "Semana de transición con resultados estables en los indicadores principales.";
      pain = "La cobranza en bolívares digitales está demorando más de lo esperado frente al efectivo.";
      opp = "Incentiva el pago contra-entrega o transferencias inmediatas para asegurar la liquidez diaria.";
    }

    return { diagnostic: diag, painPoint: pain, opportunity: opp };
  }, [route]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">

      {/* Top Section: Metrics Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard 
          label="Cumplimiento Clientes" 
          value={route.clients.real} 
          meta={route.clients.meta} 
          icon={<Users className="w-5 h-5" />}
          color={getSemaphoreColor(route.clients.real, route.clients.meta)}
        />
        <MetricCard 
          label="Cumplimiento Cajas" 
          value={route.boxes.real} 
          meta={route.boxes.meta} 
          icon={<Target className="w-5 h-5" />}
          color={getSemaphoreColor(route.boxes.real, route.boxes.meta)}
        />
        <MetricCard 
          label="Cobranza Lograda" 
          value={route.collection.real} 
          meta={route.collection.meta} 
          icon={<Wallet className="w-5 h-5" />}
          color={getSemaphoreColor(route.collection.real, route.collection.meta)}
          isCurrency
        />
      </div>

      {/* Editor Section */}
      <EditableTable route={route} onUpdate={onUpdate} />

      {/* Visualization Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* Main Bar Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-[#2E86C1]" />
            Meta vs. Real (Performance)
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                />
                <Legend iconType="circle" />
                <Bar name="Meta" dataKey="meta" fill="#2E86C1" radius={[4, 4, 0, 0]} barSize={40} />
                <Bar name="Real" dataKey="real" radius={[4, 4, 0, 0]} barSize={40}>
                  {barData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Currency Donut Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
            <Wallet className="w-5 h-5 text-[#2E86C1]" />
            Distribución de Cobranza
          </h3>
          <div className="h-80 w-full flex flex-col items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
            <div className="text-center mt-2">
              <p className="text-xs text-slate-500 uppercase font-bold">Total Cobrado</p>
              <p className="text-2xl font-black text-slate-800">
                {new Intl.NumberFormat('es-VE', { style: 'currency', currency: 'VED' }).format(route.collection.real)}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* AI Analysis Module */}
      <div className="bg-gradient-to-br from-slate-900 to-slate-800 text-white rounded-2xl p-8 shadow-xl border border-slate-700 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10">
          <BrainCircuit className="w-32 h-32" />
        </div>

        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-8">
            <div className="bg-[#2E86C1]/20 p-2 rounded-lg border border-[#2E86C1]/30">
              <BrainCircuit className="w-6 h-6 text-[#3498DB]" />
            </div>
            <div>
              <h2 className="text-xl font-bold tracking-tight">Análisis Estratégico Senior</h2>
              <p className="text-xs text-slate-400 uppercase font-bold tracking-widest">IA Consultant Insights</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="space-y-3">
              <div className="flex items-center gap-2 text-[#3498DB]">
                <TrendingDown className="w-4 h-4" />
                <h4 className="text-sm font-bold uppercase tracking-wider">Diagnóstico</h4>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed font-light">
                {analysis.diagnostic}
              </p>
            </div>

            <div className="space-y-3">
              <div className="flex items-center gap-2 text-rose-400">
                <AlertTriangle className="w-4 h-4" />
                <h4 className="text-sm font-bold uppercase tracking-wider">Punto de Dolor</h4>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed font-light">
                {analysis.painPoint}
              </p>
            </div>

            <div className="space-y-3">
              <div className="flex items-center gap-2 text-emerald-400">
                <Lightbulb className="w-4 h-4" />
                <h4 className="text-sm font-bold uppercase tracking-wider">Oportunidad</h4>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed font-light italic">
                {analysis.opportunity}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const MetricCard: React.FC<{ 
  label: string, 
  value: number, 
  meta: number, 
  icon: React.ReactNode, 
  color: string,
  isCurrency?: boolean 
}> = ({ label, value, meta, icon, color, isCurrency }) => {
  const percent = meta > 0 ? Math.round((value / meta) * 100) : 0;

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-slate-50 rounded-lg text-slate-400">
          {icon}
        </div>
        <div className="text-right">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}</span>
          <div className="flex items-center justify-end gap-1">
             <div className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></div>
             <span className="text-2xl font-black text-slate-800">{percent}%</span>
          </div>
        </div>
      </div>
      <div className="flex items-end justify-between">
        <div>
          <p className="text-xs text-slate-400 font-medium">Logro Actual</p>
          <p className="text-lg font-bold text-slate-700">
            {isCurrency ? new Intl.NumberFormat('es-VE').format(value) : value}
          </p>
        </div>
        <div className="text-right">
          <p className="text-xs text-slate-400 font-medium">Meta</p>
          <p className="text-sm font-bold text-slate-500">
            {isCurrency ? new Intl.NumberFormat('es-VE').format(meta) : meta}
          </p>
        </div>
      </div>
      <div className="mt-4 w-full bg-slate-100 rounded-full h-1.5 overflow-hidden">
        <div 
          className="h-full rounded-full transition-all duration-1000" 
          style={{ width: `${Math.min(100, percent)}%`, backgroundColor: color }}
        ></div>
      </div>
    </div>
  );
};

export default DashboardView;

