interface DashboardViewProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ route, onUpdate }) => {
  // Lógica de Semáforo: Rojo < 70%, Amarillo 71-90%, Verde > 91%
  const getSemaphoreColor = (real: number, meta: number) => {
    if (meta <= 0) return '#27AE60';
    const percent = (real / meta) * 100;
    if (percent < 70) return '#E74C3C'; // Rojo
    if (percent <= 90) return '#F1C40F'; // Amarillo
    return '#27AE60'; // Verde
  };

  const barData = useMemo(() => [
    { name: 'Clientes', meta: route.clients.meta, real: route.clients.real, color: getSemaphoreColor(route.clients.real, route.clients.meta) },
    { name: 'Cajas', meta: route.boxes.meta, real: route.boxes.real, color: getSemaphoreColor(route.boxes.real, route.boxes.meta) },
    { name: 'Cobranza', meta: route.collection.meta, real: route.collection.real, color: getSemaphoreColor(route.collection.real, route.collection.meta) },
  ], [route]);

  const pieData = useMemo(() => {
    const digital = Math.max(0, route.collection.real - route.divisas);
    return [
      { name: 'Bs. Digital', value: digital, color: '#3498DB' },
      { name: 'Divisas Cash', value: route.divisas, color: '#2ECC71' }
    ];
  }, [route.collection.real, route.divisas]);

  const analysis = useMemo(() => {
    const clientPerf = (route.clients.real / (route.clients.meta || 1)) * 100;
    const boxesPerf = (route.boxes.real / (route.boxes.meta || 1)) * 100;
    const collPerf = (route.collection.real / (route.collection.meta || 1)) * 100;

    let diag = `${route.name.split(' (')[0]}, revisemos tus indicadores de la semana. `;
    let pain = "";
    let opp = "";

    if (clientPerf > 90 && boxesPerf < 75) {
      diag += "Tu cobertura de clientes es excelente, lo que indica una buena disciplina en el recorrido de la ruta.";
      pain = "Sin embargo, el volumen de cajas por cliente está en zona roja. Estás visitando los puntos pero la venta no tiene profundidad.";
      opp = "Para la próxima semana, enfócate en el portafolio secundario. No salgas del cliente sin ofrecer al menos un SKU adicional al habitual.";
    } else if (clientPerf < 70) {
      diag += "La activación de clientes está por debajo del estándar esperado para tu zona.";
      pain = "El riesgo es alto: estás concentrando el volumen en pocos clientes. Si uno falla, tu meta se desploma.";
      opp = "Dedica el lunes y martes exclusivamente a 'recuperación de cartera'. Visita esos clientes que no te han comprado en los últimos 15 días.";
    } else if (boxesPerf > 95 && collPerf < 80) {
      diag += "¡Excelente volumen de ventas! Has logrado una penetración de mercado sobresaliente.";
      pain = "Pero cuidado: la cobranza no está siguiendo el ritmo de la venta. Estamos comprometiendo el flujo de caja.";
      opp = "Prioriza el cierre de facturas pendientes antes de liberar nuevos despachos. El control de crédito es vital ahora.";
    } else if (boxesPerf < 50) {
      diag += "Los números de volumen están en estado crítico para esta ruta.";
      pain = "Vemos que el mercado está activo pero tu participación ha caído drásticamente frente a la meta establecida.";
      opp = "Necesitamos una reunión urgente de estrategia para evaluar precios o bonificaciones especiales en tus clientes clave.";
    } else {
      diag += "Mantienes un desempeño equilibrado, rozando las metas institucionales en la mayoría de KPIs.";
      pain = "La cobranza en divisas cash representa una parte importante, asegúrate de los procesos de verificación de billetes.";
      opp = "Incrementa la meta de cajas un 10% para la siguiente semana aprovechando la estabilidad actual.";
    }

    return { diagnostic: diag, painPoint: pain, opportunity: opp };
  }, [route]);

