              <TrendingUp className="w-4 h-4 text-[#2E86C1]" />
              Comparativa Meta vs. Real
            </h3>
            <div className="flex gap-4 text-[10px] font-bold uppercase text-slate-400">
              <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-[#2E86C1]"></div> Meta</div>
              <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-slate-400"></div> Real</div>
            </div>
          </div>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Bar name="Meta" dataKey="meta" fill="#2E86C1" radius={[4, 4, 0, 0]} barSize={32} />
                <Bar name="Real" dataKey="real" radius={[4, 4, 0, 0]} barSize={32}>
                  {barData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
