          {icon}
        </div>
        <div className="text-right">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
          <div className="flex items-center justify-end gap-1.5 mt-1">
             <div className="w-2 h-2 rounded-full animate-pulse" style={{ backgroundColor: color }}></div>
             <span className="text-2xl font-black text-slate-800 leading-none">{percent}%</span>
          </div>
        </div>
      </div>
      <div className="flex items-end justify-between">
        <div>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">Real</p>
          <p className="text-lg font-bold text-slate-700">
            {isCurrency ? new Intl.NumberFormat('es-VE').format(value) : value}
          </p>
        </div>
        <div className="text-right">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">Meta</p>
          <p className="text-xs font-bold text-slate-400">
            {isCurrency ? new Intl.NumberFormat('es-VE').format(meta) : meta}
          </p>
        </div>
      </div>
      <div className="mt-4 w-full bg-slate-100 rounded-full h-1.5 overflow-hidden">
        <div 
          className="h-full rounded-full transition-all duration-700 ease-out" 
          style={{ width: `${Math.min(100, percent)}%`, backgroundColor: color }}
        ></div>
      </div>
    </div>
  );
};

