const MetricCard: React.FC<{ 
  label: string, 
  value: number, 
  meta: number, 
  icon: React.ReactNode, 
  color: string,
  isCurrency?: boolean,
  unit?: string
}> = ({ label, value, meta, icon, color, isCurrency, unit }) => {
  const percent = meta > 0 ? Math.round((value / meta) * 100) : 0;

  return (
    <div className="bg-white p-7 rounded-3xl shadow-sm border border-slate-200 hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-300 group">
      <div className="flex justify-between items-start mb-6">
        <div className="p-3 bg-slate-50 rounded-2xl text-slate-400 group-hover:bg-[#2E86C1]/10 group-hover:text-[#2E86C1] transition-colors">
          {icon}
