        <div className="text-right">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
          <div className="flex items-center justify-end gap-2 mt-1">
             <div className="w-2.5 h-2.5 rounded-full animate-pulse shadow-sm" style={{ backgroundColor: color }}></div>
             <span className="text-3xl font-black text-slate-800 leading-none">{percent}%</span>
          </div>
        </div>
      </div>

      <div className="flex items-end justify-between bg-slate-50/50 p-4 rounded-2xl border border-slate-100">
        <div>
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Resultado</p>
          <p className="text-xl font-black text-slate-700">
            {isCurrency ? new Intl.NumberFormat('es-VE').format(value) : value}
            <span className="text-xs font-bold text-slate-400 ml-1 uppercase">{unit}</span>
          </p>
        </div>
        <div className="text-right border-l border-slate-200 pl-4">
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Meta</p>
