        <div className="bg-slate-50/50 border-t border-slate-100">
          <div className="max-w-[1440px] mx-auto px-4">
            <nav className="flex items-center gap-2 overflow-x-auto no-scrollbar py-2 scroll-smooth" aria-label="Tabs">
