interface EditableTableProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const EditableTable: React.FC<EditableTableProps> = ({ route, onUpdate }) => {
  const handleChange = (field: keyof RouteData, subField: string, value: string) => {
    const numValue = parseFloat(value) || 0;
    const updated = { ...route };

    if (field === 'divisas') {
      updated.divisas = numValue;
    } else if (field === 'clients' || field === 'boxes' || field === 'collection') {
      const stat = updated[field] as { meta: number, real: number };
      if (subField === 'meta') stat.meta = numValue;
      if (subField === 'real') stat.real = numValue;
    }

    onUpdate(updated);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50 flex items-center gap-2">
