      </div>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-200">
          <thead>
            <tr className="bg-white">
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Indicador</th>
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Meta</th>
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Real</th>
              <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase">Detalle Adicional</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-100">
            {/* Clientes */}
            <tr>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-700">Clientes (Activación)</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.meta}
