interface DashboardViewProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ route, onUpdate }) => {
  // Protocolo de Semáforo: Rojo < 70%, Amarillo 71-90%, Verde > 91%
  const getSemaphoreColor = (real: number, meta: number) => {
    if (meta <= 0) return '#27AE60';
    const percent = (real / meta) * 100;
    if (percent < 70) return '#E74C3C'; // Rojo
    if (percent <= 90) return '#F1C40F'; // Amarillo
    return '#27AE60'; // Verde
  };

  const barData = useMemo(() => [
    { 
      name: 'Clientes', 
      meta: 100, 
      real: Math.round((route.clients.real / (route.clients.meta || 1)) * 100), 
      color: getSemaphoreColor(route.clients.real, route.clients.meta) 
    },
    { 
      name: 'Cajas', 
      meta: 100, 
      real: Math.round((route.boxes.real / (route.boxes.meta || 1)) * 100), 
      color: getSemaphoreColor(route.boxes.real, route.boxes.meta) 
    },
    { 
      name: 'Cobranza', 
      meta: 100, 
      real: Math.round((route.collection.real / (route.collection.meta || 1)) * 100), 
      color: getSemaphoreColor(route.collection.real, route.collection.meta) 
    },
  ], [route]);

  const pieData = useMemo(() => {
    const digital = Math.max(0, route.collection.real - route.divisas);
    return [
      { name: 'Transferencia (USD)', value: digital, color: '#3498DB' },
      { name: 'Efectivo (USD)', value: route.divisas, color: '#2ECC71' }
    ];
  }, [route.collection.real, route.divisas]);

  const analysis = useMemo(() => {
    const clientPerf = (route.clients.real / (route.clients.meta || 1)) * 100;
    const boxesPerf = (route.boxes.real / (route.boxes.meta || 1)) * 100;
    const collPerf = (route.collection.real / (route.collection.meta || 1)) * 100;

    const sellerName = route.name.split(' - ')[0];
    const routeName = route.name.split(' - ')[1] || 'General';

    let diag = `${sellerName}, analizando la ruta de ${routeName}: `;
    let pain = "";
    let opp = "";

    if (clientPerf < 70) {
      diag += "La activación de clientes es crítica. Estás muy por debajo del mínimo aceptable.";
      pain = "Hay un alto riesgo de perder presencia en el mercado frente a la competencia si no visitas tus puntos.";
      opp = "Prioridad 1 para mañana: Recuperar clientes inactivos. Ofrece el combo de bienvenida para reactivarlos.";
    } else if (boxesPerf < 70) {
      diag += "Estás activando clientes pero con pedidos muy pequeños. El volumen es insuficiente.";
      pain = "Tus costos de logística están superando el margen de venta por cada entrega realizada.";
      opp = "Enfócate en la 'Venta Sugerida'. Intenta que cada cliente que ya activaste te compre al menos 2 cajas más de lo habitual.";
    } else if (collPerf < 80) {
      diag += "La venta está fluyendo pero la cobranza se está estancando. El flujo de caja está en riesgo.";
      pain = "Facturas vencidas en la calle significan capital de trabajo paralizado para el grupo.";
      opp = "No liberes nuevos pedidos a clientes con deuda mayor a 7 días. La cobranza es tu objetivo principal esta semana.";
    } else if (clientPerf >= 91 && boxesPerf >= 91) {
      diag += "¡Desempeño sobresaliente! Has logrado un equilibrio perfecto entre cobertura y volumen.";
      pain = "El único riesgo ahora es el desabastecimiento si no proyectamos bien la demanda de la ruta.";
      opp = "Identifica los 5 clientes top de esta ruta y preséntales el catálogo de productos premium para elevar aún más el ticket.";
    } else {
      diag += "Resultados estables pero con amplio margen de mejora en la profundidad de la venta.";
      pain = "La meta está cerca pero nos falta ese último empuje en la colocación de cajas.";
      opp = "Revisa los precios de la competencia en esta zona específica y ajustemos la oferta si es necesario para cerrar la brecha.";
    }

    return { diagnostic: diag, painPoint: pain, opportunity: opp };
  }, [route]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Visual Header for the Current Route */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-l-4 border-[#2E86C1] pl-6 py-2">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">{route.name}</h2>
          <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-1">Análisis de Desempeño Operativo (Metas en %)</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            <div className="w-8 h-8 rounded-full bg-slate-200 border-2 border-white flex items-center justify-center text-[10px] font-bold text-slate-600">V</div>
            <div className="w-8 h-8 rounded-full bg-blue-500 border-2 border-white flex items-center justify-center text-[10px] font-bold text-white">IA</div>
          </div>
          <span className="text-xs font-bold text-slate-500">Auditoría Digital Activa</span>
        </div>
      </div>

      {/* Main KPI Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard 
          label="Cobertura Clientes" 
          value={route.clients.real} 
          meta={route.clients.meta} 
          icon={<Users className="w-5 h-5" />}
          color={getSemaphoreColor(route.clients.real, route.clients.meta)}
          unit="Puntos"
        />
        <MetricCard 
          label="Volumen Cajas" 
          value={route.boxes.real} 
          meta={route.boxes.meta} 
          icon={<Target className="w-5 h-5" />}
          color={getSemaphoreColor(route.boxes.real, route.boxes.meta)}
          unit="Cjs"
        />
        <MetricCard 
          label="Efectividad Cobro" 
          value={route.collection.real} 
          meta={route.collection.meta} 
          icon={<Wallet className="w-5 h-5" />}
          color={getSemaphoreColor(route.collection.real, route.collection.meta)}
          isCurrency
          unit="USD"
        />
      </div>

      {/* Editor Module */}
      <EditableTable route={route} onUpdate={onUpdate} />

      {/* Data Visualization Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Main Bar Chart - Performance Comparison (PERCENTAGE MODE) */}
        <div className="lg:col-span-2 bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-10">
            <div className="flex items-center gap-3">
              <div className="w-1.5 h-6 bg-[#2E86C1] rounded-full"></div>
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tighter">Cumplimiento de Objetivos (%)</h3>
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-slate-100 border border-slate-200"></div>
                <span className="text-[10px] font-bold text-slate-400 uppercase">Meta (100%)</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-[#2E86C1]"></div>
                <span className="text-[10px] font-bold text-slate-400 uppercase">Logrado (%)</span>
              </div>
            </div>
          </div>

          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 800}} 
                  dy={10}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11}}
                  domain={[0, 100]}
                  tickFormatter={(val) => `${val}%`}
                />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }}
                  formatter={(value: number) => [`${value}%`, 'Valor']}
                />
                <Bar name="Objetivo Meta" dataKey="meta" fill="#e2e8f0" radius={[6, 6, 0, 0]} barSize={48} />
                <Bar name="Resultado Real" dataKey="real" radius={[6, 6, 0, 0]} barSize={48}>
                  {barData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Currency Donut Chart - Mix Logic (USD) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-black text-slate-800 mb-8 uppercase tracking-tighter flex items-center gap-2">
            <Wallet className="w-5 h-5 text-emerald-500" />
            Estructura de Cobro (USD)
          </h3>
          <div className="h-64 w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                  animationDuration={1000}
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip formatter={(val: number) => [`$${new Intl.NumberFormat('en-US').format(val)}`, 'Monto']} />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total</span>
              <span className="text-xl font-black text-slate-800">
                ${new Intl.NumberFormat('en-US').format(route.collection.real)}
              </span>
            </div>
          </div>
          <div className="mt-8 space-y-3">
            {pieData.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between p-3 rounded-xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-2">
                  <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: item.color }}></div>
                  <span className="text-xs font-bold text-slate-600">{item.name}</span>
                </div>
                <span className="text-xs font-black text-slate-800">
                  ${new Intl.NumberFormat('en-US').format(item.value)}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Advanced Feedback Panel - Gerente Virtual */}
      <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden text-white">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none scale-150 origin-top-right">
          <BrainCircuit className="w-64 h-64" />
        </div>

        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12 pb-8 border-b border-white/10">
            <div className="flex items-center gap-5">
              <div className="bg-blue-500 p-4 rounded-2xl shadow-xl shadow-blue-500/20">
                <BrainCircuit className="w-8 h-8 text-white" />
              </div>
              <div>
                <h2 className="text-2xl font-black tracking-tight">Análisis de Gerencia Virtual</h2>
                <p className="text-xs font-bold text-blue-400 uppercase tracking-[0.2em] mt-1">Feedback Estratégico Senior</p>
              </div>
            </div>
            <div className="flex items-center gap-2 px-5 py-2 bg-white/5 rounded-full border border-white/10">
              <CheckCircle2 className="w-4 h-4 text-emerald-400" />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-300">Algoritmo Verificado</span>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
            <div className="bg-white/5 p-8 rounded-3xl border border-white/10 hover:bg-white/10 transition-colors">
              <div className="flex items-center gap-3 text-blue-400 mb-5">
                <TrendingUp className="w-5 h-5" />
                <h4 className="text-xs font-black uppercase tracking-widest">Diagnóstico Actual</h4>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed font-medium">
