const MetricCard: React.FC<{ 
  label: string, 
  value: number, 
  meta: number, 
  icon: React.ReactNode, 
  color: string,
  isCurrency?: boolean,
  unit?: string
}> = ({ label, value, meta, icon, color, isCurrency, unit }) => {
  const percent = meta > 0 ? Math.round((value / meta) * 100) : 0;

  return (
    <div className="bg-white p-7 rounded-3xl shadow-sm border border-slate-200 hover:shadow-xl hover:shadow-slate-200/50 transition-all duration-300 group">
      <div className="flex justify-between items-start mb-6">
        <div className="p-3 bg-slate-50 rounded-2xl text-slate-400 group-hover:bg-[#2E86C1]/10 group-hover:text-[#2E86C1] transition-colors">
          {icon}
        </div>
        <div className="text-right">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
          <div className="flex items-center justify-end gap-2 mt-1">
             <div className="w-2.5 h-2.5 rounded-full animate-pulse shadow-sm" style={{ backgroundColor: color }}></div>
             <span className="text-3xl font-black text-slate-800 leading-none">{percent}%</span>
          </div>
        </div>
      </div>

      <div className="flex items-end justify-between bg-slate-50/50 p-4 rounded-2xl border border-slate-100">
        <div>
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Resultado</p>
          <p className="text-xl font-black text-slate-700">
            {isCurrency ? `$${new Intl.NumberFormat('en-US').format(value)}` : value}
            <span className="text-xs font-bold text-slate-400 ml-1 uppercase">{unit}</span>
          </p>
        </div>
        <div className="text-right border-l border-slate-200 pl-4">
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Meta</p>
          <p className="text-sm font-bold text-slate-400">
            {isCurrency ? `$${new Intl.NumberFormat('en-US').format(meta)}` : meta}
          </p>
        </div>
      </div>

      <div className="mt-6 w-full bg-slate-100 rounded-full h-2 overflow-hidden shadow-inner">
        <div 
          className="h-full rounded-full transition-all duration-1000 ease-out shadow-lg" 
          style={{ width: `${Math.min(100, percent)}%`, backgroundColor: color }}
        ></div>
      </div>
    </div>
  );
};

