      </div>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-200">
          <thead>
            <tr className="bg-white">
              <th className="px-6 py-4 text-left text-sm font-bold text-slate-500 uppercase tracking-wider">Indicador</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-slate-500 uppercase tracking-wider">Meta</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-slate-500 uppercase tracking-wider">Real</th>
              <th className="px-6 py-4 text-left text-sm font-bold text-slate-500 uppercase tracking-wider">Detalle Adicional</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-100">
            {/* Clientes */}
            <tr>
              <td className="px-6 py-4 whitespace-nowrap text-base font-medium text-slate-700">Clientes (Activación)</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.meta}
                  onChange={(e) => handleChange('clients', 'meta', e.target.value)}
                  className="w-28 px-3 py-2 border border-slate-200 rounded text-base focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.real}
                  onChange={(e) => handleChange('clients', 'real', e.target.value)}
                  className="w-28 px-3 py-2 border border-slate-200 rounded text-base focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <div className="flex gap-6">
                  <div className="flex flex-col gap-1">
                    <label className="text-xs font-bold text-slate-500 uppercase">Clientes Totales</label>
                    <input 
                      type="number" 
                      value={route.totalClients}
