                      className="w-32 px-3 py-2 border border-slate-200 rounded text-base focus:ring-1 focus:ring-[#2E86C1] focus:outline-none"
                    />
                  </div>
                  <div className="flex flex-col gap-1">
                    <label className="text-xs font-bold text-slate-500 uppercase">Clientes Visitados</label>
                    <input 
                      type="number" 
                      value={route.visitedClients}
