              </td>
            </tr>
            {/* Cajas */}
            <tr>
              <td className="px-6 py-4 whitespace-nowrap text-base font-medium text-slate-700">Volumen (Cajas)</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <input 
                  type="number" 
