              </div>
              <div className="p-4 bg-white/5 rounded-2xl border border-white/5">
                <p className="text-white text-sm leading-relaxed font-bold italic">
                  "{analysis.opportunity}"
                </p>
              </div>
            </div>

            <div className="bg-emerald-900/20 p-8 rounded-3xl border border-emerald-500/30 hover:bg-emerald-900/30 transition-colors">
              <div className="flex items-center gap-3 text-emerald-400 mb-5">
                <Banknote className="w-5 h-5" />
                <h4 className="text-xs font-black uppercase tracking-widest">Efectividad Divisas</h4>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed font-medium">
                {analysis.cashInsight}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const MetricCard: React.FC<{ 
  label: string, 
