            <tr className="bg-white">
              <th className="px-6 py-5 text-left text-base font-black text-slate-600 uppercase tracking-wider">Indicador</th>
              <th className="px-6 py-5 text-left text-base font-black text-slate-600 uppercase tracking-wider">Meta</th>
              <th className="px-6 py-5 text-left text-base font-black text-slate-600 uppercase tracking-wider">Real</th>
              <th className="px-6 py-5 text-left text-base font-black text-slate-600 uppercase tracking-wider">Detalle Adicional</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-100">
            {/* Clientes */}
            <tr>
              <td className="px-6 py-5 whitespace-nowrap text-lg font-bold text-slate-800">Clientes (Activación)</td>
              <td className="px-6 py-5 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.meta}
                  onChange={(e) => handleChange('clients', 'meta', e.target.value)}
                  className="w-32 px-4 py-2 border border-slate-200 rounded-lg text-lg font-semibold text-slate-700 focus:ring-2 focus:ring-[#2E86C1] focus:outline-none transition-all"
                />
              </td>
              <td className="px-6 py-5 whitespace-nowrap">
                <input 
                  type="number" 
                  value={route.clients.real}
