                  formatter={(value: number) => [`${value}%`, 'Valor']}
                />
                <Bar name="Objetivo Meta" dataKey="meta" fill="#93C5FD" radius={[6, 6, 0, 0]} barSize={64} />
                <Bar name="Resultado Real" dataKey="real" radius={[6, 6, 0, 0]} barSize={64}>
