import React, { useMemo } from 'react';
import { RouteData } from '../types';
import EditableTable from './EditableTable';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell,
  PieChart, Pie
} from 'recharts';
import { BrainCircuit, AlertTriangle, Lightbulb, TrendingDown, Target, Users, Wallet, TrendingUp, CheckCircle2, Banknote } from 'lucide-react';

interface DashboardViewProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ route, onUpdate }) => {
  // Protocolo de Semáforo: Rojo < 70%, Amarillo 71-90%, Verde > 91%
  const getSemaphoreColor = (real: number, meta: number) => {
    if (meta <= 0) return '#27AE60';
    const percent = (real / meta) * 100;
    if (percent < 70) return '#E74C3C'; // Rojo
    if (percent <= 90) return '#F1C40F'; // Amarillo
    return '#27AE60'; // Verde
  };

  const barData = useMemo(() => [
    { 
      name: 'Clientes', 
      meta: 100, 
      real: Math.round((route.clients.real / (route.clients.meta || 1)) * 100), 
      color: getSemaphoreColor(route.clients.real, route.clients.meta) 
    },
    { 
      name: 'Cajas', 
      meta: 100, 
      real: Math.round((route.boxes.real / (route.boxes.meta || 1)) * 100), 
      color: getSemaphoreColor(route.boxes.real, route.boxes.meta) 
    },
    { 
      name: 'Cobranza', 
      meta: 100, 
      real: Math.round((route.collection.real / (route.collection.meta || 1)) * 100), 
      color: getSemaphoreColor(route.collection.real, route.collection.meta) 
    },
  ], [route]);

  const pieData = useMemo(() => {
    const digital = Math.max(0, route.collection.real - route.divisas);
    return [
      { name: 'Transferencia (USD)', value: digital, color: '#3498DB' },
      { name: 'Efectivo (USD)', value: route.divisas, color: '#2ECC71' }
    ];
  }, [route.collection.real, route.divisas]);

  const analysis = useMemo(() => {
    // 1. Calculate Core KPIs
    const clientPerf = (route.clients.real / (route.clients.meta || 1)) * 100;
    const boxesPerf = (route.boxes.real / (route.boxes.meta || 1)) * 100;
    const collPerf = (route.collection.real / (route.collection.meta || 1)) * 100;

    // 2. Calculate Gaps (The Math behind the tactic)
    const pendingCollection = route.collection.meta - route.collection.real;
    const pendingBoxes = route.boxes.meta - route.boxes.real;
    const pendingClients = route.clients.meta - route.clients.real;

    // Drop Size Analysis (Cajas per Client)
    const currentDropSize = route.clients.real > 0 ? (route.boxes.real / route.clients.real).toFixed(1) : "0";

    const sellerName = route.name.split(' - ')[0];

    let diag = "";
    let pain = "";
    let opp = "";

    // --- LOGIC ENGINE: COMPLEX SCENARIOS ---

    // SCENARIO 1: "THE MIRAGE" (Selling OK, Collecting Bad) -> High Risk
    // Rules: Collection < 80% AND Boxes > 80%
    if (collPerf < 80 && boxesPerf > 80) {
      diag = `PELIGRO FINANCIERO: Estás "regalando" mercancía. Tienes ${boxesPerf.toFixed(0)}% en ventas pero tu cobranza está congelada.`;
      pain = `Capital Atrapado: Tienes $${new Intl.NumberFormat('en-US').format(pendingCollection)} en la calle. Esto frena la reposición del almacén.`;
      opp = `ORDEN TÁCTICA: Detén despachos a crédito hoy mismo. Solo libera pedidos contra pago de facturas viejas. Tu prioridad es COBRAR, no vender.`;
    } 

    // SCENARIO 2: "LOGISTIC WASTE" (Many clients, Low Volume) -> Low Productivity
    // Rules: Clients > 80% AND Boxes < 70%
    else if (clientPerf > 80 && boxesPerf < 70) {
      diag = `INEFICIENCIA LOGÍSTICA: Visitas mucho, vendes poco. Tu drop-size es de solo ${currentDropSize} cajas/cliente.`;
      pain = `Costos Operativos: El gasto de combustible y tiempo por parada está consumiendo tu margen de ganancia.`;
      opp = `ESTRATEGIA DE MIX: No aceptes pedidos de menos de 5 cajas. Ofrece el producto de mayor rotación solo si llevan uno de baja rotación (Venta Cruzada).`;
    }

    // SCENARIO 3: "CONTRACTION" (Low Clients) -> Market Loss
    // Rules: Clients < 70%
    else if (clientPerf < 70) {
      diag = `PÉRDIDA DE TERRITORIO: Has dejado de atender a ${pendingClients} clientes meta. La competencia está llenando esos vacíos.`;
      pain = `Riesgo Futuro: Cliente que no visitas hoy, es cliente que compra a la competencia mañana y no recuperas en meses.`;
      opp = `OPERACIÓN RESCATE: Imprime tu lista de inactivos. Ofrece una bonificación o descuento especial solo por "Reactivación" esta semana.`;
    }

    // SCENARIO 4: "LOW PERFORMANCE" (Everything Low) -> Crisis
    // Rules: Clients < 70% AND Boxes < 70% AND Collection < 70%
    else if (clientPerf < 70 && boxesPerf < 70 && collPerf < 70) {
      diag = `ALARMA ROJA: Ruta colapsada en todos los indicadores. Tendencia negativa sostenida.`;
      pain = `Viabilidad: Con estos números, la ruta no es rentable para la compañía ni para tus comisiones.`;
      opp = `REINGENIERÍA TOTAL: Olvida la meta mensual. Enfócate en vender ${Math.ceil(pendingBoxes/6)} cajas diarias por los próximos 6 días. Divide y vencerás.`;
    }

    // SCENARIO 5: "STAR PERFORMER" (Everything > 90%) -> Maintenance
    else if (clientPerf >= 90 && boxesPerf >= 90 && collPerf >= 90) {
      diag = `EXCELENCIA OPERATIVA: Dominio total de la zona. Has superado las expectativas estándar.`;
      pain = `Abastecimiento: El único riesgo es romper stock debido a la alta demanda generada.`;
      opp = `EXPANSIÓN: Ya cubriste la meta. Usa el tiempo restante para introducir SKUs nuevos que el cliente nunca ha comprado (Innovación).`;
    }

    // DEFAULT SCENARIO: "AVERAGE / STABLE"
    else {
      diag = `DESEMPEÑO ESTABLE: Estás en el promedio, pero te faltan ${pendingBoxes} cajas para asegurar el bono.`;
      pain = `Costo de Oportunidad: Estás dejando dinero en la mesa por no cerrar con fuerza el 20% restante.`;
      opp = `PUSH FINAL: Revisa los 10 clientes con mayor volumen histórico y adelanta sus pedidos de la próxima semana para este cierre.`;
    }

    // --- CASH INTELLIGENCE ---
    const cashRatio = route.collection.real > 0 ? (route.divisas / route.collection.real) * 100 : 0;
    let cashMsg = "";

    if (cashRatio < 30) {
      cashMsg = "CRÍTICO: Exceso de bolívares/transferencias. Necesitamos DIVISAS para reposición inmediata. Exige min 50% en $ efectivo.";
    } else if (cashRatio < 60) {
      cashMsg = "ACEPTABLE: El flujo permite operar, pero intenta subir la captación de divisas en clientes mayoristas.";
    } else {
      cashMsg = "SOBRESALIENTE: Alta liquidez en divisas. Esto nos da poder de negociación con proveedores. ¡Mantén esa presión!";
    }

    return { diagnostic: diag, painPoint: pain, opportunity: opp, cashInsight: cashMsg };
  }, [route]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Visual Header for the Current Route */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-l-4 border-[#2E86C1] pl-6 py-2">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">{route.name}</h2>
          <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-1">Análisis de Desempeño Operativo (Metas en %)</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex -space-x-2">
            <div className="w-8 h-8 rounded-full bg-slate-200 border-2 border-white flex items-center justify-center text-[10px] font-bold text-slate-600">V</div>
            <div className="w-8 h-8 rounded-full bg-blue-500 border-2 border-white flex items-center justify-center text-[10px] font-bold text-white">IA</div>
          </div>
          <span className="text-xs font-bold text-slate-500">Auditoría Digital Activa</span>
        </div>
      </div>

      {/* Main KPI Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard 
          label="Cobertura Clientes" 
          value={route.clients.real} 
          meta={route.clients.meta} 
          icon={<Users className="w-6 h-6" />}
          color={getSemaphoreColor(route.clients.real, route.clients.meta)}
          unit="Puntos"
        />
        <MetricCard 
          label="Volumen Cajas" 
          value={route.boxes.real} 
          meta={route.boxes.meta} 
          icon={<Target className="w-6 h-6" />}
          color={getSemaphoreColor(route.boxes.real, route.boxes.meta)}
          unit="Cjs"
        />
        <MetricCard 
          label="Efectividad Cobro" 
          value={route.collection.real} 
          meta={route.collection.meta} 
          icon={<Wallet className="w-6 h-6" />}
          color={getSemaphoreColor(route.collection.real, route.collection.meta)}
          isCurrency
          unit="USD"
        />
      </div>

      {/* Editor Module */}
      <EditableTable route={route} onUpdate={onUpdate} />

      {/* Data Visualization Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Main Bar Chart - Performance Comparison (PERCENTAGE MODE) */}
        <div className="lg:col-span-2 bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-10">
            <div className="flex items-center gap-3">
              <div className="w-1.5 h-6 bg-[#2E86C1] rounded-full"></div>
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tighter">Cumplimiento de Objetivos (%)</h3>
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
