               <div className="flex items-center px-4 py-3 text-slate-500 border-r border-slate-800 mr-2">
                  <Globe className="w-4 h-4" />
                </div>
                {routes.map((route) => {
                  const isActive = activeRouteId === route.id;
                  const [seller, routeName] = route.name.includes(' - ') ? route.name.split(' - ') : [route.name, ''];

                  return (
                    <button
                      key={route.id}
                      onClick={() => setActiveRouteId(route.id)}
                      className={`
                        relative group flex flex-col items-start px-5 py-3 transition-all duration-200 min-w-[140px]
                        ${isActive 
                          ? 'bg-slate-800' 
                          : 'hover:bg-slate-800/50'
