                    >
                      {isActive && <div className="absolute top-0 left-0 w-full h-0.5 bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]"></div>}
                      <span className={`text-[10px] font-black uppercase tracking-tighter mb-0.5 ${isActive ? 'text-blue-400' : 'text-slate-500 group-hover:text-slate-400'}`}>
                        {seller}
                      </span>
                      <span className={`text-xs font-bold whitespace-nowrap ${isActive ? 'text-white' : 'text-slate-400 group-hover:text-slate-200'}`}>
                        {routeName || 'Principal'}
                      </span>
                    </button>
                  );
                })}
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-grow max-w-[1600px] mx-auto w-full px-4 sm:px-6 lg:px-8 py-10 space-y-10">
        <DashboardView 
          route={activeRoute} 
          onUpdate={handleUpdateData} 
        />
      </main>

      {/* Footer */}
      <footer className="border-t border-slate-200 bg-white py-10">
        <div className="max-w-7xl mx-auto px-4 flex flex-col items-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3">FV Grupo Empresarial • Sistema Confidencial</p>
          <div className="flex items-center gap-4 text-xs font-medium text-slate-500">
            <span>&copy; 2026 Plataforma de Inteligencia</span>
            <span className="text-slate-300">•</span>
            <span>v2.5.0 Enterprise</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { RouteData } from '../types';
import EditableTable from './EditableTable';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell,
  PieChart, Pie
} from 'recharts';
import { BrainCircuit, AlertTriangle, Lightbulb, Target, Users, Wallet, TrendingUp, CheckCircle2, Banknote, MapPin, ChevronRight, Activity } from 'lucide-react';

interface DashboardViewProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ route, onUpdate }) => {
  // Protocolo de Semáforo: Rojo < 70%, Amarillo 71-90%, Verde > 91%
  const getSemaphoreColor = (real: number, meta: number) => {
    if (meta <= 0) return '#10b981'; // Emerald 500
    const percent = (real / meta) * 100;
    if (percent < 70) return '#ef4444'; // Red 500
    if (percent <= 90) return '#f59e0b'; // Amber 500
    return '#10b981'; // Emerald 500
  };

  const barData = useMemo(() => [
    { 
      name: 'Clientes', 
      meta: 100, 
      real: Math.round((route.clients.real / (route.clients.meta || 1)) * 100), 
      color: getSemaphoreColor(route.clients.real, route.clients.meta) 
    },
    { 
      name: 'Cajas', 
      meta: 100, 
      real: Math.round((route.boxes.real / (route.boxes.meta || 1)) * 100), 
      color: getSemaphoreColor(route.boxes.real, route.boxes.meta) 
    },
    { 
      name: 'Cobranza', 
      meta: 100, 
      real: Math.round((route.collection.real / (route.collection.meta || 1)) * 100), 
      color: getSemaphoreColor(route.collection.real, route.collection.meta) 
    },
  ], [route]);

  const pieData = useMemo(() => {
    const digital = Math.max(0, route.collection.real - route.divisas);
    return [
      { name: 'Transferencia', value: digital, color: '#94a3b8' }, // Slate 400
      { name: 'Efectivo', value: route.divisas, color: '#0ea5e9' } // Sky 500
    ];
  }, [route.collection.real, route.divisas]);

  const analysis = useMemo(() => {
    // 1. Calculate Core KPIs
    const clientPerf = (route.clients.real / (route.clients.meta || 1)) * 100;
    const boxesPerf = (route.boxes.real / (route.boxes.meta || 1)) * 100;
    const collPerf = (route.collection.real / (route.collection.meta || 1)) * 100;

    // 2. Calculate Gaps
    const pendingCollection = route.collection.meta - route.collection.real;
    const pendingBoxes = route.boxes.meta - route.boxes.real;
    const pendingClients = route.clients.meta - route.clients.real;
    const currentDropSize = route.clients.real > 0 ? (route.boxes.real / route.clients.real).toFixed(1) : "0";

    let diag = "", pain = "", opp = "";

    // SCENARIO 1: "THE MIRAGE" (Selling OK, Collecting Bad)
    if (collPerf < 80 && boxesPerf > 80) {
      diag = `DESEQUILIBRIO FINANCIERO DETECTADO. Ventas al ${boxesPerf.toFixed(0)}% con cobranza rezagada.`;
      pain = `Riesgo de Liquidez: $${new Intl.NumberFormat('en-US').format(pendingCollection)} pendientes por reintegrar.`;
      opp = `ACCIÓN INMEDIATA: Bloquear nuevos despachos hasta regularizar facturas vencidas. Prioridad: Recuperación de Capital.`;
    } 
    // SCENARIO 2: "LOGISTIC WASTE" (Many clients, Low Volume)
    else if (clientPerf > 80 && boxesPerf < 70) {
      diag = `BAJA RENTABILIDAD POR PARADA. Drop-size promedio: ${currentDropSize} cajas.`;
      pain = `Impacto Margen: El costo logístico supera el beneficio de la venta actual.`;
      opp = `ESTRATEGIA DE VOLUMEN: Implementar mínimo de 5 cajas por pedido o aplicar venta cruzada obligatoria.`;
    }
    // SCENARIO 3: "CONTRACTION" (Low Clients)
    else if (clientPerf < 70) {
      diag = `PÉRDIDA DE CUOTA DE MERCADO. Cobertura al ${clientPerf.toFixed(0)}%.`;
      pain = `Fuga de Clientes: ${pendingClients} puntos de venta inactivos expuestos a la competencia.`;
      opp = `PLAN DE REACTIVACIÓN: Ejecutar ruta de barrido exclusiva para inactivos con oferta de gancho.`;
    }
    // SCENARIO 4: "CRISIS"
    else if (clientPerf < 70 && boxesPerf < 70 && collPerf < 70) {
      diag = `RENDIMIENTO CRÍTICO MULTI-FACTORIAL. Tendencia negativa generalizada.`;
      pain = `Viabilidad Operativa: La ruta no cubre sus costos fijos actuales.`;
      opp = `GESTIÓN DE CRISIS: Micro-objetivos diarios. Meta para mañana: ${Math.ceil(pendingBoxes/6)} cajas.`;
    }
    // SCENARIO 5: "STAR"
    else if (clientPerf >= 90 && boxesPerf >= 90 && collPerf >= 90) {
      diag = `EJECUCIÓN DE ALTO RENDIMIENTO. Indicadores en rango de excelencia.`;
      pain = `Gestión de Inventario: Monitorear stock para evitar quiebres por alta demanda.`;
      opp = `FIDELIZACIÓN: Introducir mix de productos premium en el top 20% de clientes.`;
    }
    // DEFAULT
    else {
      diag = `RENDIMIENTO ESTÁNDAR CON OPORTUNIDAD DE MEJORA.`;
      pain = `Brecha de Cierre: Faltan ${pendingBoxes} cajas para alcanzar el bono objetivo.`;
      opp = `ACELERACIÓN DE CIERRE: Adelantar pedidos programados de la próxima semana.`;
    }

    // CASH INTELLIGENCE
    const cashRatio = route.collection.real > 0 ? (route.divisas / route.collection.real) * 100 : 0;
    let cashMsg = "";
    if (cashRatio < 30) cashMsg = "ALERTA DE TESORERÍA: Mix de efectivo bajo crítico. Requerido aumentar captación de divisas.";
    else if (cashRatio < 60) cashMsg = "FLUJO ESTABLE: Mix de pago dentro de parámetros operativos aceptables.";
    else cashMsg = "LIQUIDEZ ÓPTIMA: Excelente posición de efectivo para reposición de inventario.";

    return { diagnostic: diag, painPoint: pain, opportunity: opp, cashInsight: cashMsg };
  }, [route]);

  return (
    <div className="space-y-10 animate-in fade-in duration-700">

      {/* 1. ROUTE SUMMARY HEADER */}
      <div className="bg-white rounded-xl p-8 shadow-sm border-l-4 border-blue-600 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <MapPin className="w-4 h-4 text-blue-500" />
            <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Territorio Asignado</span>
          </div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">{route.name}</h2>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-right hidden md:block">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Estado de Auditoría</p>
            <div className="flex items-center justify-end gap-2 text-emerald-600">
              <Activity className="w-4 h-4" />
              <span className="font-bold">Datos en Tiempo Real</span>
            </div>
          </div>
          <div className="h-10 w-px bg-slate-200 hidden md:block"></div>
          <div className="bg-slate-50 px-6 py-3 rounded-lg border border-slate-100">
            <span className="block text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mb-1">Efectividad Global</span>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-black text-blue-600">
                {Math.round(((route.clients.real/route.clients.meta) + (route.boxes.real/route.boxes.meta) + (route.collection.real/route.collection.meta))/3 * 100)}%
              </span>
              <span className="text-xs font-bold text-slate-400">IPG</span>
            </div>
          </div>
        </div>
      </div>

      {/* 2. EXECUTIVE KPI CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard 
          label="Cobertura de Mercado" 
          value={route.clients.real} 
          meta={route.clients.meta} 
          icon={<Users className="w-5 h-5" />}
          color={getSemaphoreColor(route.clients.real, route.clients.meta)}
          unit="Clientes"
        />
        <MetricCard 
          label="Volumen Despachado" 
          value={route.boxes.real} 
          meta={route.boxes.meta} 
          icon={<Target className="w-5 h-5" />}
          color={getSemaphoreColor(route.boxes.real, route.boxes.meta)}
          unit="Cajas"
        />
        <MetricCard 
          label="Recuperación de Capital" 
          value={route.collection.real} 
          meta={route.collection.meta} 
          icon={<Wallet className="w-5 h-5" />}
          color={getSemaphoreColor(route.collection.real, route.collection.meta)}
          isCurrency
          unit="USD"
        />
      </div>

      {/* 3. VIRTUAL MANAGER (AI) SECTION - EXECUTIVE STYLE */}
      <div className="relative overflow-hidden rounded-2xl bg-[#1e293b] text-white shadow-2xl border border-slate-700">
        <div className="absolute top-0 right-0 p-0 pointer-events-none opacity-10">
           <BrainCircuit className="w-96 h-96 -mr-20 -mt-20 text-blue-400" />
        </div>

        <div className="relative z-10 p-8 md:p-10">
          <div className="flex items-center gap-4 mb-10 border-b border-slate-700 pb-6">
            <div className="p-3 bg-blue-600 rounded-lg shadow-lg shadow-blue-900/50">
              <BrainCircuit className="w-6 h-6 text-white" />
            </div>
            <div>
              <h3 className="text-2xl font-bold tracking-tight text-white">Gerencia Virtual Inteligente</h3>
              <p className="text-xs font-bold text-blue-400 uppercase tracking-[0.2em]">Análisis Táctico & Estratégico</p>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-x-12 gap-y-10">
            {/* Left Column: Diagnosis & Risk */}
            <div className="space-y-8">
              <div>
                <div className="flex items-center gap-3 mb-3 text-slate-400">
                  <Activity className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-widest">Diagnóstico Situacional</span>
                </div>
                <p className="text-lg text-slate-200 font-medium leading-relaxed border-l-2 border-blue-500 pl-4">
                  {analysis.diagnostic}
                </p>
              </div>

              <div>
                <div className="flex items-center gap-3 mb-3 text-slate-400">
                  <AlertTriangle className="w-4 h-4 text-amber-500" />
                  <span className="text-xs font-bold uppercase tracking-widest">Punto Crítico</span>
                </div>
                <p className="text-lg text-slate-200 font-medium leading-relaxed border-l-2 border-amber-500 pl-4">
                  {analysis.painPoint}
                </p>
              </div>
            </div>

            {/* Right Column: Opportunity & Cash */}
            <div className="space-y-8">
              <div className="bg-blue-900/30 p-6 rounded-xl border border-blue-500/30 backdrop-blur-sm">
                <div className="flex items-center gap-3 mb-4 text-emerald-400">
                  <Lightbulb className="w-5 h-5" />
                  <span className="text-xs font-black uppercase tracking-widest">Orden Táctica</span>
                </div>
                <p className="text-xl text-white font-bold leading-relaxed italic">
                  "{analysis.opportunity}"
                </p>
              </div>

              <div>
                <div className="flex items-center gap-3 mb-3 text-slate-400">
                  <Banknote className="w-4 h-4 text-emerald-500" />
                  <span className="text-xs font-bold uppercase tracking-widest">Salud Financiera (Divisas)</span>
                </div>
                <p className="text-sm text-slate-300 font-medium leading-relaxed">
                  {analysis.cashInsight}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 4. VISUALIZATION & DATA ENTRY */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        {/* Performance Chart */}
        <div className="xl:col-span-2 bg-white p-8 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-end mb-8">
            <div>
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">Cumplimiento vs Meta</h3>
              <p className="text-xs font-medium text-slate-400 mt-1">Comparativa porcentual de KPIs clave</p>
            </div>
            <div className="flex gap-4">
               <div className="flex items-center gap-2">
                 <span className="w-3 h-3 rounded-full bg-slate-200"></span>
                 <span className="text-[10px] font-bold uppercase text-slate-500">Meta (100%)</span>
               </div>
               <div className="flex items-center gap-2">
                 <span className="w-3 h-3 rounded-full bg-blue-600"></span>
                 <span className="text-[10px] font-bold uppercase text-slate-500">Real</span>
               </div>
            </div>
          </div>

          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData} margin={{ top: 10, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 12, fontWeight: 700}} 
                  dy={15}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11}}
                  domain={[0, 100]}
                  tickFormatter={(val) => `${val}%`}
                />
                <Tooltip 
                  cursor={{fill: '#f1f5f9'}}
                  contentStyle={{ borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                  formatter={(value: number, name: string) => [`${value}%`, name === 'Objetivo Meta' ? 'META' : 'Real']}
                />
                <Bar name="Objetivo Meta" dataKey="meta" fill="#e2e8f0" radius={[4, 4, 0, 0]} barSize={50} />
                <Bar name="Resultado Real" dataKey="real" radius={[4, 4, 0, 0]} barSize={50}>
                  {barData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Collection Mix & Data Table */}
        <div className="space-y-8">
           {/* Currency Mix */}
           <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200">
             <div className="flex items-center gap-2 mb-6">
                <Wallet className="w-5 h-5 text-blue-600" />
                <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Mix de Cobranza</h3>
             </div>

             <div className="flex flex-row items-center justify-between">
                <div className="h-40 w-40 relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={pieData}
                        cx="50%"
                        cy="50%"
                        innerRadius={45}
                        outerRadius={65}
                        paddingAngle={5}
                        dataKey="value"
                      >
                        {pieData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                        ))}
                      </Pie>
                      <Tooltip formatter={(val: number) => [`$${new Intl.NumberFormat('en-US').format(val)}`, '']} />
                    </PieChart>
                  </ResponsiveContainer>
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <span className="text-xs font-black text-slate-700">USD</span>
                  </div>
                </div>

                <div className="space-y-4 flex-1 pl-4">
                   {pieData.map((item, idx) => (
                     <div key={idx}>
                       <div className="flex items-center gap-2 mb-1">
                         <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color }}></div>
                         <span className="text-[10px] font-bold text-slate-400 uppercase">{item.name}</span>
                       </div>
                       <p className="text-lg font-bold text-slate-800">
                         ${new Intl.NumberFormat('en-US').format(item.value)}
                       </p>
                     </div>
                   ))}
                </div>
             </div>
           </div>

           {/* Quick Actions / Editor Link */}
           <EditableTable route={route} onUpdate={onUpdate} />
        </div>
      </div>
    </div>
  );
};

const MetricCard: React.FC<{ 
  label: string, 
  value: number, 
  meta: number, 
  icon: React.ReactNode, 
  color: string,
  isCurrency?: boolean,
  unit?: string
}> = ({ label, value, meta, icon, color, isCurrency, unit }) => {
  const percent = meta > 0 ? Math.round((value / meta) * 100) : 0;

  return (
    <div className="bg-white p-6 rounded-xl shadow-[0_2px_10px_-3px_rgba(6,81,237,0.1)] border border-slate-100 relative overflow-hidden group hover:border-blue-200 transition-colors">
      <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity transform scale-150">
        {icon}
      </div>

      <div className="flex flex-col h-full justify-between">
        <div className="mb-4">
          <div className="flex items-center gap-2 text-slate-400 mb-2">
            {icon}
            <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          </div>
          <div className="flex items-baseline gap-1">
            <span className="text-4xl font-black text-slate-800 tracking-tight">
              {isCurrency ? `$${new Intl.NumberFormat('en-US').format(value)}` : value}
            </span>
            <span className="text-xs font-bold text-slate-400 uppercase">{unit}</span>
          </div>
        </div>

        <div>
          <div className="flex justify-between items-end mb-2">
             <span className="text-xs font-medium text-slate-400">Meta: {isCurrency ? `$${new Intl.NumberFormat('en-US').format(meta)}` : meta}</span>
             <span className="text-sm font-black" style={{ color }}>{percent}%</span>
          </div>
          <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
            <div 
              className="h-full rounded-full transition-all duration-1000" 
              style={{ width: `${Math.min(100, percent)}%`, backgroundColor: color }}
            ></div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DashboardView;

import React from 'react';
import { RouteData } from '../types';
import { Settings2 } from 'lucide-react';

interface EditableTableProps {
  route: RouteData;
  onUpdate: (updated: RouteData) => void;
}

const EditableTable: React.FC<EditableTableProps> = ({ route, onUpdate }) => {
  const handleChange = (field: keyof RouteData, subField: string, value: string) => {
    const numValue = parseFloat(value) || 0;
    const updated = { ...route };

    if (field === 'divisas' || field === 'totalClients' || field === 'visitedClients') {
      // @ts-ignore
      updated[field] = numValue;
    } else if (field === 'clients' || field === 'boxes' || field === 'collection') {
      const stat = updated[field] as { meta: number, real: number };
      if (subField === 'meta') stat.meta = numValue;
      if (subField === 'real') stat.real = numValue;
    }

    onUpdate(updated);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="px-6 py-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Settings2 className="w-4 h-4 text-slate-400" />
          <h3 className="text-xs font-black text-slate-600 uppercase tracking-widest">Ajuste de Datos Operativos</h3>
        </div>
        <span className="text-[10px] font-bold text-slate-300 uppercase">Modo Edición</span>
      </div>

      <div className="p-0">
        <table className="w-full">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-100">
              <th className="px-6 py-3 text-left text-[10px] font-black text-slate-400 uppercase tracking-wider">KPI / Indicador</th>
              <th className="px-4 py-3 text-left text-[10px] font-black text-slate-400 uppercase tracking-wider">Objetivo</th>
              <th className="px-4 py-3 text-left text-[10px] font-black text-slate-400 uppercase tracking-wider">Real</th>
              <th className="px-4 py-3 text-left text-[10px] font-black text-slate-400 uppercase tracking-wider w-1/3">Variables Adicionales</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
